  while (s && guard++ < 50) { let pat = '', m; if ((m = s.match(/^(BEGIN|END)\s*\{/))) { pat = m[1]; s = s.slice(m[0].length - 1); } else if (s[0] !== '{') { const i = s.indexOf('{'); pat = i < 0 ? s : s.slice(0, i).trim(); s = i < 0 ? '' : s.slice(i); } if (!s.startsWith('{')) { blocks.push({ pat, body: 'print' }); break; } let dep = 0, k = 0; for (; k < s.length; k++) { if (s[k] === '{') dep++; else if (s[k] === '}') { dep--; if (!dep) break; } } blocks.push({ pat, body: s.slice(1, k) }); s = s.slice(k + 1).trim(); }
